//go:build e2e

package e2e

// The harness of the Debian acceptance tests (R-DEB-035, T-17 WP10): the repositories of a test, a publisher with a token, the four APT
// clients of deb_clients_test.go driven through `kubectl exec`, the control client of the counting Debian archive test upstream, and the
// packages the tests upload (generated by test/debstub/debgen, each installing a script that prints a fixed line). The scenarios are in
// deb_local_test.go (upload with curl, apt-get update and install, the anonymous read, the wrong keyring), deb_remote_test.go (pull-through,
// the flat root), deb_rotation_test.go (the rotation table of R-DEB-017), deb_mirror_test.go and deb_virtual_test.go. docs/developer/e2e.md
// describes the whole.
//
// Every client runs the setup snippets the setup API renders for the repository (Q-DEB-27), unchanged, with the token in $TROVE_TOKEN, and
// APT runs with --error-on=any, so that a warning fails the row. Nothing sets trusted=yes.

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/guided-traffic/trove/test/debstub"
	"github.com/guided-traffic/trove/test/debstub/debgen"
)

const (
	debPublisher = "e2e-deb" // the publisher: read, deploy and delete on every repository named deb-*
	debSuite     = "stable"  // the suite of the setup snippets
)

// debFixture is the installation the Debian tests share: created once per run, idempotent over runs.
type debFixture struct {
	adm   *api
	token string // the publisher's token
	run   string // six hex digits, part of every repository and package name this run creates
}

var (
	debFxOnce sync.Once
	debFxVal  *debFixture
	debFxErr  error
)

// debFx puts the cluster into the scatter profile (three packages replicas, every request to another one; two workers claim the index builds)
// and creates the publisher.
func debFx(t testing.TB) *debFixture {
	t.Helper()
	useScatter(t)
	debFxOnce.Do(func() {
		debFxErr = fmt.Errorf("the fixture did not finish (see the first failure)")
		debFxVal, debFxErr = buildDebFixture(t)
	})
	if debFxErr != nil {
		t.Fatalf("Debian fixture: %v", debFxErr)
	}
	return debFxVal
}

func buildDebFixture(t testing.TB) (*debFixture, error) {
	adm := adminAPI(t)
	b := make([]byte, 3)
	_, _ = rand.Read(b)
	fx := &debFixture{adm: adm, run: hex.EncodeToString(b)}
	ensureSA(t, adm, debPublisher)
	// one policy for every repository of the suite (an instance-wide policy selects by <projectGlob>/<keyGlob>, R-AUTHZ-004), so that a
	// repository a test creates is readable as soon as the replicas know it
	ensurePolicy(t, adm, debPublisher, []string{"deb-*"}, [2]any{"sa:" + debPublisher, []string{"read", "deploy", "delete"}})
	fx.token = freshSAToken(t, adm, debPublisher, 4*3600, map[string]any{"inherit": true}).Token
	return fx, nil
}

// registry is a client of the edge with the publisher's token as a direct credential.
func (fx *debFixture) registry(t testing.TB) *api { return newAPI(t).withToken(fx.token) }

// repoPath is the path of a repository's address below the host: /api/deb/<project>/<key>.
func debRepoPath(key string) string { return "/api/deb/" + repoRef(key) }

// repoURL is the address an APT source names for the repository: the base URL of the edge, with the trailing slash of the snippets.
func debRepoURL(t testing.TB, key string) string {
	return "https://" + aptEdge(t) + debRepoPath(key) + "/"
}

// name is a package name of this run: unique per scenario and run, so that a rerun on the same cluster never meets a version that exists
// (the bytes of a stored version are immutable, R-DEB-006). It starts with trove- like the packages of the test archive, which the
// reset of a client removes.
func (fx *debFixture) name(group string) string { return "trove-e2e-" + fx.run + "-" + group }

// localRepo creates a local Debian repository for one test: authentication required unless the purpose is "open" (anonymous read,
// deb-open-*). The repository goes with the test.
func (fx *debFixture) localRepo(t testing.TB, purpose string, settings map[string]any) string {
	t.Helper()
	key := fmt.Sprintf("deb-%s-%s", purpose, fx.run)
	body := map[string]any{"key": key, "class": "local", "format": "deb", "requireAuthentication": !strings.HasPrefix(purpose, "open")}
	if settings != nil {
		body["deb"] = settings
	}
	fx.createRepo(t, key, body)
	return key
}

// remoteRepo creates a pull-through remote repository over a path of the counting Debian archive test upstream, with the stub's key a as
// deb.upstreamKeys (the upstream's certificates, which the repository serves as signing-key.asc and the clients trust).
func (fx *debFixture) remoteRepo(t testing.TB, purpose, archivePath string, settings map[string]any) string {
	t.Helper()
	key := fmt.Sprintf("deb-%s-%s", purpose, fx.run)
	remote := map[string]any{"url": "https://" + debStubHost(t) + archivePath, "mode": "pullThrough"}
	for k, v := range settings {
		remote[k] = v
	}
	body := map[string]any{
		"key": key, "class": "remote", "format": "deb", "requireAuthentication": true, "remote": remote,
		"deb": map[string]any{"upstreamKeys": string(debStub(t).keyring(t, "a"))},
	}
	fx.createRepo(t, key, body)
	return key
}

func (fx *debFixture) createRepo(t testing.TB, key string, body map[string]any) {
	t.Helper()
	fx.adm.do(http.MethodPost, reposRoute, body).want(t, "create "+key, 201)
	// A repository that stays behind is asked by the shadowing check of every first upload into a local member, and the clients of a
	// later run must not meet it: the repository goes with the test.
	t.Cleanup(func() { deleteRepository(t, fx.adm, key) })
	debReadableOnEveryReplica(t, fx.token, key)
}

// debReadableOnEveryReplica waits until each packages replica lets the token read the new repository (the bound of R-AUTHZ-028 plus one
// second for the poll and the request): the key file of every Debian repository with keys answers 200.
func debReadableOnEveryReplica(t testing.TB, token string, keys ...string) {
	t.Helper()
	addrs, stop := packagesForwards(t)
	defer stop()
	const within = 10 * time.Second
	for i, addr := range addrs {
		a := apiAtPod(t, addr, token)
		for _, key := range keys {
			start := time.Now()
			for {
				r := a.getOverForward(debRepoPath(key) + "/signing-key.asc")
				if r.Status == 200 {
					break
				}
				if time.Since(start) > within {
					t.Fatalf("replica %d: repository %s answered %s after its creation, want 200 within %s (R-AUTHZ-028)", i, key, r, within)
				}
				time.Sleep(100 * time.Millisecond)
			}
		}
	}
}

// ── packages ─────────────────────────────────────────────────────────────────

// debPackage is a package the tests upload: architecture all, so that it is listed under every architecture of the clients' pods.
type debPackage struct {
	name, version string
	data          []byte
	file          string
}

func newDebPackage(t testing.TB, name, version string) debPackage {
	t.Helper()
	spec := debgen.Hello(name, version, "all")
	d, err := debgen.Build(spec)
	if err != nil {
		t.Fatal(err)
	}
	return debPackage{name: name, version: version, data: d.Bytes, file: spec.Filename()}
}

// line is what the installed script prints.
func (p debPackage) line() string {
	return fmt.Sprintf("hello from %s %s (all)", p.name, p.version)
}

// uploadPath is the path of the upload route with the suite and component.
func (p debPackage) uploadPath(key, suite, component string) string {
	q := url.Values{"distribution": {suite}, "component": {component}}
	return debRepoPath(key) + "/upload/" + p.file + "?" + q.Encode()
}

// upload sends the package as the publisher and returns the change sequence of the suite its answer names (R-DEB-006).
func (fx *debFixture) upload(t testing.TB, key string, p debPackage, suite string) int64 {
	t.Helper()
	r := fx.registry(t).do(http.MethodPut, p.uploadPath(key, suite, "main"), p.data, "Content-Type", "application/vnd.debian.binary-package")
	r.want(t, "upload "+p.file+" to "+key, 201)
	return uploadSeq(t, r.Body, suite)
}

// uploadSeq reads the change sequence of a suite from the body of an upload answer.
func uploadSeq(t testing.TB, body []byte, suite string) int64 {
	t.Helper()
	var u struct {
		Index []struct {
			Distribution string `json:"distribution"`
			ChangeSeq    int64  `json:"changeSeq"`
		} `json:"index"`
	}
	if err := json.Unmarshal(body, &u); err != nil {
		t.Fatalf("the upload answer is not JSON: %v\n%s", err, body)
	}
	for _, i := range u.Index {
		if i.Distribution == suite {
			return i.ChangeSeq
		}
	}
	t.Fatalf("the upload answer names no change sequence of the suite %s: %s", suite, body)
	return 0
}

// ── the index state and the signing keys ─────────────────────────────────────

// debSuiteState is one suite of the index state (R-DEB-014).
type debSuiteState struct {
	Distribution string   `json:"distribution"`
	ChangeSeq    int64    `json:"changeSeq"`
	PublishedSeq int64    `json:"publishedSeq"`
	Generation   int64    `json:"generation"`
	State        string   `json:"state"`
	SignedBy     []string `json:"signedBy"`
}

// indexState reads the state of a suite; waitFor is the "<suite>:<changeSeq>" the read waits for (empty: no wait).
func (fx *debFixture) indexState(t testing.TB, key, suite string, waitFor int64) debSuiteState {
	t.Helper()
	path := repoAPI(key) + "/deb/index"
	if waitFor > 0 {
		path += fmt.Sprintf("?waitFor=%s:%d", suite, waitFor)
	}
	r := fx.adm.get(path).want(t, "index state of "+key, 200)
	var s struct {
		Suites []debSuiteState `json:"suites"`
	}
	r.JSON(t, &s)
	for _, x := range s.Suites {
		if x.Distribution == suite {
			return x
		}
	}
	return debSuiteState{Distribution: suite}
}

// awaitPublished waits, with the index state read of R-DEB-014, until a generation of the suite lists the change sequence of an upload.
func (fx *debFixture) awaitPublished(t testing.TB, key, suite string, seq int64) debSuiteState {
	t.Helper()
	return fx.awaitSuite(t, key, suite, seq, 2*time.Minute, func(s debSuiteState) bool { return s.PublishedSeq >= seq })
}

// awaitSuite reads the state of the suite, waiting for the change sequence at each read, until the condition holds.
func (fx *debFixture) awaitSuite(t testing.TB, key, suite string, seq int64, within time.Duration, ok func(debSuiteState) bool) debSuiteState {
	t.Helper()
	var s debSuiteState
	waitFor(t, fmt.Sprintf("the index of %s/%s to reach the state asked for", key, suite), within, 200*time.Millisecond, func() bool {
		s = fx.indexState(t, key, suite, seq)
		return ok(s)
	})
	return s
}

// debKey is a signing key of the key list (R-DEB-015).
type debKey struct {
	Fingerprint string `json:"fingerprint"`
	State       string `json:"state"`
	Origin      string `json:"origin"`
	PublicKey   string `json:"publicKey"`
	// KeyCreatedAt is the creation time of the key, BoundSince the time of its earliest binding self-signature (Q-DEB-40).
	KeyCreatedAt time.Time `json:"keyCreatedAt"`
	BoundSince   time.Time `json:"boundSince"`
}

func (fx *debFixture) signingKeys(t testing.TB, key string) []debKey {
	t.Helper()
	r := fx.adm.get(repoAPI(key)+"/deb/signing-keys").want(t, "signing keys of "+key, 200)
	var l struct {
		Keys []debKey `json:"keys"`
	}
	r.JSON(t, &l)
	return l.Keys
}

// keyIn returns the key of the state ("primary", "next"); the test fails when there is none.
func (fx *debFixture) keyIn(t testing.TB, key, state string) debKey {
	t.Helper()
	for _, k := range fx.signingKeys(t, key) {
		if k.State == state {
			return k
		}
	}
	t.Fatalf("%s has no %s signing key: %+v", key, state, fx.signingKeys(t, key))
	return debKey{}
}

// signingKeyFile is the block of certificates the repository serves for its clients (R-DEB-018).
func (fx *debFixture) signingKeyFile(t testing.TB, key string) []byte {
	t.Helper()
	return fx.registry(t).do(http.MethodGet, debRepoPath(key)+"/signing-key.asc", nil).want(t, "signing-key.asc of "+key, 200).Body
}

// ── the setup snippets ───────────────────────────────────────────────────────

// setupSnippets are the snippets of the client setup of a repository by id (credentials=env: the token is the reference $TROVE_TOKEN).
func (fx *debFixture) setupSnippets(t testing.TB, key, pkg, version string) map[string]string {
	t.Helper()
	q := url.Values{"client": {"apt"}, "credentials": {"env"}, "package": {pkg}, "version": {version}}
	r := fx.adm.get(repoAPI(key)+"/client-setup?"+q.Encode()).want(t, "client setup of "+key+" for apt", 200)
	var setup struct {
		Snippets []struct {
			ID      string `json:"id"`
			Content string `json:"content"`
		} `json:"snippets"`
	}
	r.JSON(t, &setup)
	out := map[string]string{}
	for _, s := range setup.Snippets {
		out[s.ID] = s.Content
	}
	return out
}

// debNameOf is the name the snippets derive from the repository: the key file, the source file and the credential file are
// trove-<project>-<repository> below /etc/apt (R-DEB-029).
func debNameOf(key string) string { return "trove-" + e2eProject + "-" + key }

func debKeyFile(key string) string { return "/etc/apt/keyrings/" + debNameOf(key) + ".asc" }
func debSourceFile(key string) string {
	return "/etc/apt/sources.list.d/" + debNameOf(key) + ".sources"
}
func debAuthFile(key string) string { return "/etc/apt/auth.conf.d/" + debNameOf(key) + ".conf" }

// ── the clients ──────────────────────────────────────────────────────────────

// aptClient is one scenario in the pod of one image. It starts from a pod without the files of an earlier scenario and leaves none.
type aptClient struct {
	t   testing.TB
	img aptImage
	fx  *debFixture
}

func (fx *debFixture) client(t testing.TB, img aptImage) *aptClient {
	t.Helper()
	c := &aptClient{t: t, img: img, fx: fx}
	c.reset()
	t.Cleanup(c.reset)
	return c
}

// sh runs a shell script in the pod with the publisher's token as $TROVE_TOKEN.
func (c *aptClient) sh(script string) (string, error) {
	c.t.Helper()
	return aptTry(c.t, c.img, []string{"TROVE_TOKEN=" + c.fx.token}, script)
}

func (c *aptClient) must(script string) string {
	c.t.Helper()
	out, err := c.sh(script)
	if err != nil {
		c.t.Fatalf("%s: %v\n%s\n%s", c.img.name, err, script, tailLines(out, 30))
	}
	return out
}

// reset removes everything a scenario of this suite leaves in the pod: the sources, keyrings and credentials of the snippets, the lists
// and the test packages.
func (c *aptClient) reset() {
	c.t.Helper()
	const script = `rm -f /etc/apt/sources.list.d/trove-* /etc/apt/keyrings/trove-* /etc/apt/auth.conf.d/trove-*
rm -rf /var/lib/apt/lists/*
pkgs=$(dpkg-query -W -f '${Package} ' 'trove-*' 'libtrove*' 2>/dev/null || true)
if [ -n "$pkgs" ]; then apt-get purge --yes $pkgs >/dev/null; fi`
	if out, err := c.sh(script); err != nil {
		c.t.Errorf("reset %s: %v\n%s", c.img.name, err, tailLines(out, 20))
	}
}

// configure runs the configure snippet of the repository unchanged (the key command, the source file, the credential file for a
// repository that requires authentication).
func (c *aptClient) configure(key string) {
	c.t.Helper()
	snippets := c.fx.setupSnippets(c.t, key, "trove-hello", "1.0")
	script := snippets["apt.configure.shell"]
	if script == "" {
		c.t.Fatalf("the setup of %s for apt has no snippet apt.configure.shell: %v", key, sortedKeys(snippets))
	}
	c.must(script)
}

// update is `apt-get update --error-on=any`: a warning is a failure.
func (c *aptClient) update() (string, error) {
	c.t.Helper()
	return c.sh("apt-get update --error-on=any")
}

func (c *aptClient) mustUpdate() string {
	c.t.Helper()
	out, err := c.update()
	if err != nil {
		c.t.Fatalf("apt-get update --error-on=any on %s: %v\n%s", c.img.name, err, tailLines(out, 30))
	}
	return out
}

// install installs packages (nothing else is recommended) and returns the output.
func (c *aptClient) install(pkgs ...string) (string, error) {
	c.t.Helper()
	return c.sh("apt-get install --yes --no-install-recommends " + strings.Join(pkgs, " "))
}

// mustInstallAndRun installs the package and runs the script it installs: the line it prints is the package's own.
func (c *aptClient) mustInstallAndRun(spec, name, want string) {
	c.t.Helper()
	if out, err := c.install(spec); err != nil {
		c.t.Fatalf("apt-get install %s on %s: %v\n%s", spec, c.img.name, err, tailLines(out, 30))
	}
	out, err := c.sh("/usr/bin/" + name)
	if err != nil || strings.TrimSpace(out) != want {
		c.t.Fatalf("%s on %s printed %q (%v), want %q", name, c.img.name, strings.TrimSpace(out), err, want)
	}
}

// verificationFailure matches what the verifiers of the four clients say when a keyring does not hold the key of the signature: sqv
// (APT 3.0) and gpgv (APT 2.4 to 2.8) word it differently, and APT adds its own line.
var verificationFailure = regexp.MustCompile(`(?i)NO_PUBKEY|public key is not available|is not signed|signatures couldn't be verified|could not be verified|not bound|Missing key|no valid|signature`)

func (c *aptClient) mustFailVerification(what string) {
	c.t.Helper()
	out, err := c.update()
	if err == nil {
		c.t.Fatalf("%s: apt-get update --error-on=any on %s succeeded, want a failure\n%s", what, c.img.name, tailLines(out, 20))
	}
	if !verificationFailure.MatchString(out) {
		c.t.Fatalf("%s: apt-get update on %s failed, but not with a signature failure:\n%s", what, c.img.name, tailLines(out, 30))
	}
}

// ── the counting test upstream ───────────────────────────────────────────────

var (
	debStubOnce sync.Once
	debStubVal  *stubControl
)

// debStubHost is the host of the Debian archive test upstream as deploy/dev/e2e.sh exports it.
func debStubHost(t testing.TB) string {
	t.Helper()
	host := os.Getenv("TROVE_E2E_DEBSTUB_HOST")
	if host == "" {
		t.Fatal("TROVE_E2E_DEBSTUB_HOST is not set; run `deploy/dev/e2e.sh deb`")
	}
	return host
}

// debStub is the control client of the counting Debian archive test upstream; reset and resetAll of the npm stub's client work on it as
// well (the control API has the same shape), debMode, debCounts and keyring are the Debian ones.
func debStub(t testing.TB) *stubControl {
	t.Helper()
	host := debStubHost(t)
	debStubOnce.Do(func() { debStubVal = newStubControl(t, "svc/debstub", host, "trove-debstub", 30*time.Second) })
	return debStubVal
}

// debMode replaces the switches of the test upstream; the zero Mode clears them.
func (s *stubControl) debMode(t testing.TB, m debstub.Mode) {
	t.Helper()
	s.send(t, http.MethodPost, "/-/stub/mode", m)
}

// debCounts reads the counters of the test upstream.
func (s *stubControl) debCounts(t testing.TB) debstub.Counts {
	t.Helper()
	var c debstub.Counts
	if err := json.Unmarshal(s.send(t, http.MethodGet, "/-/stub/counts", nil), &c); err != nil {
		t.Fatal(err)
	}
	return c
}

// keyring is the armored block of the stub's public keys of the names (a, b, c).
func (s *stubControl) keyring(t testing.TB, names ...string) []byte {
	t.Helper()
	return s.send(t, http.MethodGet, "/-/stub/keyring?names="+strings.Join(names, ","), nil)
}

// trimLine is the output of a command without the line ending around it.
func trimLine(s string) string { return strings.TrimSpace(s) }
